fn all_characters_same(s: &[u8]) -> bool {
    // An empty slice or a single-element slice trivially has all identical characters.
    if s.len() <= 1 {
        return true;
    }

    // Grab the first byte and compare all others against it.
    let first = s[0];
    for &b in &s[1..] {
        if b != first {
            return false;
        }
    }
    true
}

